mapper.select:
SELECT id, boardTitle, boardWriter, boardPass, boardContents, boardHits, FORMAT(createdAt, 'yyyy-MM-dd') as createdAt
FROM board_table
WHERE id = #{id}

mapper.update:
UPDATE board_table
SET boardHits = boardHits + 1
WHERE id = #{id}

UPDATE board_table
SET boardTitle = #{boardTitle}, boardContents = #{boardContents}
WHERE id = #{id}
